"webhook": {
      "enabled": true,
      "url": "https://maker.ifttt.com/trigger/<YOUREVENT>/with/key/<YOURKEY>/",
      "entry": {
          "value1": "买入 {pair}",
          "value2": "限价 {limit:8f}",
          "value3": "{stake_amount:8f} {stake_currency}"
      },
      "entry_cancel": {
          "value1": "取消 {pair} 的开放买单",
          "value2": "限价 {limit:8f}",
          "value3": "{stake_amount:8f} {stake_currency}"
      },
       "entry_fill": {
          "value1": "{pair} 买单已成交",
          "value2": "成交价 {open_rate:8f}",
          "value3": ""
      },
      "exit": {
          "value1": "退出 {pair}",
          "value2": "限价 {limit:8f}",
          "value3": "利润: {profit_amount:8f} {stake_currency} ({profit_ratio})"
      },
      "exit_cancel": {
          "value1": "取消 {pair} 的开放卖单",
          "value2": "限价 {limit:8f}",
          "value3": "利润: {profit_amount:8f} {stake_currency} ({profit_ratio})"
      },
      "exit_fill": {
          "value1": "{pair} 卖单已成交",
          "value2": "成交价 {close_rate:8f}",
          "value3": ""
      },
      "status": {
          "value1": "状态: {status}",
          "value2": "",
          "value3": ""
      }
  },
